#include "ib/status_screen.h"
#include <algorithm>
#include <cstdio>
#include <stdexcept>
#include <vector>
int main(int argc,char**argv){try{if(argc!=2||!ib::text::load(std::filesystem::path(argv[1])/"assets/fonts"))return 2;using namespace ib;namespace s=status;unsigned checks=0;auto check=[&](bool b){++checks;if(!b)throw std::runtime_error("status screen regression");};int last=0;for(int n=1;n<=s::LitLevels;++n){const int value=s::nativeLevel(n,2047);check(value>last&&value<=2047&&s::nearestStep(value,2047)==n);last=value;}check(last==2047&&s::nativeLevel(0,2047)==0&&s::nativeLevel(6,2047)==-1&&s::nativeLevel(1,4)==-1&&s::nearestStep(2048,2047)==-1);
 std::vector<std::uint32_t> pixels(1632*2160,0xffffffffu);Canvas canvas({pixels,1620,2160,1632});Targets targets;s::Model model;model.clock="23:59";model.zone="UTC";s::bar(canvas,targets,model,s::ReaderBar);check(targets.rect(s::Open).x1==1496&&targets.find(1250,50)==s::Open);check(std::any_of(pixels.begin(),pixels.end(),[](auto p){return p!=0xffffffffu;}));check(s::ReaderBar.x1<=1620-112);
 model.battery=73;model.wifi=0;model.charging=true;model.light=819;model.maximum=2047;s::panel(canvas,targets,model);check(targets.find(1250,50)==s::Open);for(int n=0;n<=5;++n){const auto r=targets.rect(n?s::LevelBase+n-1:s::LightOff);check(r.x1-r.x0>=96&&r.y1-r.y0>=96&&r.x0>=s::Panel.x0&&r.x1<=s::Panel.x1);check(targets.find((r.x0+r.x1)/2,(r.y0+r.y1)/2)==(n?s::LevelBase+n-1:s::LightOff));}check(!targets.rect(s::Wifi).empty()&&!targets.rect(s::Battery).empty());std::fill(pixels.begin(),pixels.end(),0xffffffffu);targets.clear();model.clockOnly=true;s::bar(canvas,targets,model,s::ReaderClock);const auto clockOnly=pixels;check(targets.rect(s::Open).x0==1280&&targets.find(1200,50)==-1);model.battery=3;model.wifi=1;model.charging=false;std::fill(pixels.begin(),pixels.end(),0xffffffffu);targets.clear();s::bar(canvas,targets,model,s::ReaderClock);check(pixels==clockOnly);check(std::all_of(pixels.begin()+8*1632+1080,pixels.begin()+8*1632+1280,[](auto p){return p==0xffffffffu;}));std::printf("STATUS_SCREEN_PASS checks=%u lit_levels=5 off=separate vendor_calls=0 input_opens=0\n",checks);return 0;}catch(const std::exception& e){std::fprintf(stderr,"STATUS_SCREEN_FAIL %s\n",e.what());return 1;}}
